import styled from '@emotion/styled';
import PropTypes from 'prop-types';
import Img from 'gatsby-image';
import { StyledBgImageContainer } from './_shared/styled-image-container';
import React from 'react';
import ButtonLink from './links/button-link';
import ScrollIndicator from './scroll-indicator';
import { mq } from './_shared/media';
import { StyledSection } from './_shared/styled-section';

const StyledHeroSection = styled(StyledSection)`
  min-height: calc(100vh - 2 * var(--header-height));
  position: relative;

  ${mq.gt.sm} {
    min-height: calc(100vh - var(--header-height));
  }
`;
const StyledIntroduction = styled.div`
  
  // margin-left: -200px;
  width: 100%;
  max-width: 500px;
  color: var(--primary-color);
  font-weight: normal;
`;
const StyledAuthor = styled.h1`
  // margin-left: -200px !important;
  // margin-top: -10px ;
  font-size: 40px;
  line-height: 1.1;
  margin: 0;
  word-break: break-word;

  ${mq.gt.xs} {
    font-size: 76px;
  }
`;
const StyledTagline = styled.h2`
  // margin-left: -200px !important;
  margin-top: 5px ;
  // padding-right : -50rem;
  font-size: 20px;
  line-height: 1.1;
  color: var(--primary-color);
  word-break: break-word;

  ${mq.gt.xs} {
    font-size: 56px;
  }
`;
const StyledDescription = styled.div`
  // margin-left: -200px;
  margin-top: 0.5rem;
  width: 100%;
  max-width: 500px;
`;
const StyledHeroContainer = styled.article`
  width: 90%; 
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  grid-gap: 2.5rem;
  padding: 2.5rem 0;

  ${mq.gt.sm} {
    grid-template-columns: repeat(2, 1fr);
  }
`;
const Hero = ({ data }) => {
  const { introduction, author, tagline, description, ctaLink, ctaLabel, about_image } = data;
  const image = about_image ? about_image.childImageSharp.fluid : null;
  return (
    <StyledHeroSection>
      <StyledHeroContainer>
      <div>
        <StyledIntroduction>{introduction}</StyledIntroduction>
        <StyledAuthor>{author}</StyledAuthor>
        <StyledTagline>{tagline}</StyledTagline>
        <StyledDescription dangerouslySetInnerHTML={{ __html: description }} />
        <ButtonLink label={ctaLabel} link={ctaLink} />
        <ScrollIndicator />
      </div>
      {image && (
            <StyledBgImageContainer>
              <Img fluid={image} objectFit="contain" />
            </StyledBgImageContainer>
          )}
          
      </StyledHeroContainer>      
    </StyledHeroSection>
  );
};

Hero.propTypes = {
  data: PropTypes.object.isRequired,
};

export default Hero;
