import styled from '@emotion/styled';
import PropTypes from 'prop-types';
import React from 'react';
import Img from 'gatsby-image';
import { StyledImageContainer } from './_shared/styled-image-container';
import SocialIcons from './social-icons';
import { mq } from './_shared/media';
import { StyledH1 } from './_shared/styled-headings';
import { StyledSection } from './_shared/styled-section';
import StyledSkewedSection from './skewed-section';

const StyledTextSection = styled.section`
  white-space: pre-line;
`;
const StyledFeatureGridContainer = styled.section`
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  grid-gap: 2.5rem;
  margin-top: 2.5rem;
  width: 100%;

  ${mq.gt.xs} {
    grid-template-columns: repeat(2, 1fr);
  }
  ${mq.gt.sm} {
    grid-template-columns: repeat(3, 1fr);
  }
`;
const StyledFeatureCard = styled.article`
  border: 1px solid var(--body-color);
  border-radius: var(--radius);

  display: flex;
  align-items: center;
  flex-direction: column;
  min-height: 200px;
  padding: 1rem;

  & svg {
    height: 2rem;
    width: 2rem;
    font-size: 2rem;
  }
`;
const StyledCardLabel = styled.h2`
  font-size: 1.5rem;
  margin: 1rem 0;
  color: var(--body-color);
`;
const StyledDivider = styled.div`
  width: 15%;
  height: 2px;
  background-color: var(--primary-color);
  margin-bottom: 1rem;
`;
const StyledFeatureDescription = styled.p`
  font-style: italic;
  font-size: 0.8rem;
`;
const StyledNav = styled.nav`
  flex: 1;
  height: 100%;
  display: none;

  ${mq.gt.sm} {
    display: flex;
    align-items: stretch;
    margin-left: 0.75rem;
  }

  & > a {
    color: var(--title-color);
    &:hover {
      color: var(--primary-color);
    }
  }
`;

const CardGrid = ({ cards, description, title, id = null }) => {
    const firstLetter = title[0];
    title = title.slice(1);
    const yellowText = {
        color: '#F1B631'
    };
    const featureCards = cards.map(({ label, description, email, instagramURL, twitterURL, githubURL, linkedinURL, profilePic }, index) => {
        const socialIconList = [
            {
                name: 'github',
                link: '',
                prefix: 'fab',
            },
            {
                name: 'linkedin',
                link: '',
                prefix: 'fab',
            },
            {
                name: 'telegram',
                link: '',
                prefix: 'fab',
            },
            {
                name: 'instagram',
                link: '',
                prefix: 'fab',
            },
            {
                name: 'twitter',
                link: '',
                prefix: 'fab',
            },
        ];
        socialIconList[0].link = githubURL;
        socialIconList[1].link = linkedinURL;
        socialIconList[2].link = email
        socialIconList[3].link = instagramURL
        socialIconList[4].link = twitterURL
        const image = profilePic ? profilePic.childImageSharp.fluid : null;
        return (
            <StyledFeatureCard key={index}>
                <StyledCardLabel>{label}</StyledCardLabel>
                <StyledDivider></StyledDivider>
                {image && (
                    <StyledImageContainer>
                        <Img fluid={image} objectFit="contain" />
                    </StyledImageContainer>
                )}
                <br />
                <StyledDivider></StyledDivider>
                <StyledFeatureDescription>{description}</StyledFeatureDescription>
                <StyledNav>
                </StyledNav>
                <SocialIcons icons={socialIconList} />
            </StyledFeatureCard>
        );
    });

    return (
        <StyledSkewedSection angle={10}>
            <StyledSection id={"members"}>
                {title && <StyledH1><span style={yellowText}>{firstLetter}</span>{title}</StyledH1>}
                <StyledTextSection dangerouslySetInnerHTML={{ __html: description }} />
                <StyledFeatureGridContainer>{featureCards}</StyledFeatureGridContainer>
            </StyledSection>
        </StyledSkewedSection>
    );
};

CardGrid.propTypes = {
    cards: PropTypes.array.isRequired,
    description: PropTypes.string.isRequired,
    id: PropTypes.string,
    title: PropTypes.string,
    githubURL: PropTypes.string.isRequired,
    linkedinURL: PropTypes.string.isRequired,
    twitterURL: PropTypes.string.isRequired,
    instagramURL: PropTypes.string.isRequired,
    email: PropTypes.string.isRequired,
};

export default CardGrid;